from __future__ import annotations

from pathlib import Path

from magic_mirror import sources


def _make_volume(root: Path, name: str, filename: str, content: str) -> Path:
    volume = root / name
    volume.mkdir(parents=True)
    path = volume / filename
    path.write_text(content)
    return path


def test_find_usb_genome_detects_23andme(tmp_path, monkeypatch):
    monkeypatch.setattr(sources, "_mount_roots", lambda: iter([tmp_path]))
    _make_volume(
        tmp_path, "USB", "genome.txt",
        "# This data file generated by 23andMe\nrsid\tchromosome\tposition\tgenotype\n",
    )
    _make_volume(tmp_path, "OTHER", "notes.txt", "grocery list\n")

    found = sources.find_usb_genome()
    assert found is not None
    assert found.name == "genome.txt"


def test_find_usb_genome_ignores_non_genome(tmp_path, monkeypatch):
    monkeypatch.setattr(sources, "_mount_roots", lambda: iter([tmp_path]))
    _make_volume(tmp_path, "USB", "readme.txt", "nothing genetic here\n")
    assert sources.find_usb_genome() is None


def test_find_local_genome_in_drop_folder(tmp_path):
    folder = tmp_path / "dna"
    folder.mkdir()
    (folder / "notes.txt").write_text("not a genome\n")
    (folder / "mydna.txt").write_text(
        "# This data file generated by 23andMe\nrsid\tchromosome\tposition\tgenotype\n"
    )
    found = sources.find_local_genome(folder)
    assert found is not None and found.name == "mydna.txt"


def test_find_local_genome_missing_folder(tmp_path):
    assert sources.find_local_genome(tmp_path / "nope") is None


def test_looks_like_23andme(tmp_path):
    good = tmp_path / "g.txt"
    good.write_text("rsid\tchromosome\tposition\tgenotype\nrs1\t1\t1\tAA\n")
    bad = tmp_path / "b.txt"
    bad.write_text("just prose\n")
    assert sources.looks_like_23andme(good)
    assert not sources.looks_like_23andme(bad)


def test_looks_like_ancestrydna(tmp_path):
    banner = tmp_path / "AncestryDNA.txt"
    banner.write_text(
        "#AncestryDNA raw data download\n"
        "rsid\tchromosome\tposition\tallele1\tallele2\nrs1\t1\t1\tA\tG\n"
    )
    header_only = tmp_path / "h.txt"
    header_only.write_text("rsid\tchromosome\tposition\tallele1\tallele2\n")
    assert sources.looks_like_23andme(banner)      # vendor banner
    assert sources.looks_like_23andme(header_only)  # rsid + allele1 columns
